function mergeTerminalThemeCatalogs(...catalogs) {
  const merged = {};
  for (const catalog of catalogs) {
    for (const [name2, theme] of Object.entries(catalog)) {
      if (Object.prototype.hasOwnProperty.call(merged, name2)) {
        throw new Error(`Duplicate terminal theme name: ${name2}`);
      }
      merged[name2] = theme;
    }
  }
  return merged;
}
